MAKE CODE: Blink LED without delay
language arduino
// Blink LED on pin 13 every 0.5 seconds using millis() timing.
// This avoids blocking the processor, allowing other code to run.

const int ledPin = 13;          // Pin connected to the LED
unsigned long previousMillis = 0; // Stores the last time the LED was updated
const long interval = 500;      // Interval in milliseconds (0.5 seconds)
int state = LOW;                // Current state of the LED

void setup() {
  pinMode(ledPin, OUTPUT);    // Initialize the LED pin as an output
}

void loop() {
  unsigned long currentMillis = millis(); // Get the current time

  // Check if the interval has passed since the last update
  if (currentMillis - previousMillis >= interval) {
    previousMillis = currentMillis;       // Update the last time the LED was updated
    state = !state;                       // Toggle the LED state (HIGH to LOW or LOW to HIGH)
    digitalWrite(ledPin, state);          // Set the LED to the new state
  }
  // The loop continues immediately without waiting, allowing other tasks to run
}
END

