// Calculate current (I) from voltage (V) and resistance (R) using Ohm's Law: I = V / R
// Then print the result for 12V and 4 ohms.

function calculateCurrent(voltage, resistance) {
  if (resistance === 0) {
    throw new Error("Resistance cannot be zero.");
  }
  return voltage / resistance;
}

// Example usage: 12 Volts across 4 Ohms
const V = 12;
const R = 4;
const I = calculateCurrent(V, R);

console.log(`Voltage: ${V} V, Resistance: ${R} Ohms`);
console.log(`Current: ${I} A`);
END

MAKE CODE: Tank Fill Control
language st
// Tank Fill Control in Structured Text (IEC 61131-3)
// Logic: Open fill valve when Low Float is ON, close when High Float is ON.
// Inputs:
//   LowFloat  : BOOL - Active when water is low (switch closed)
//   HighFloat : BOOL - Active when water is high (switch closed)
// Outputs:
//   FillValve : BOOL - Active to open the fill valve

PROGRAM TankFill
VAR
    LowFloat    : BOOL;  // Input: Low level switch
    HighFloat   : BOOL;  // Input: High level switch
    FillValve   : BOOL;  // Output: Fill valve control
END_VAR

// Simple logic: Open valve if Low is active AND High is NOT active.
// If High is active, close the valve regardless of Low.
// If Low is inactive (water is high enough), close the valve.
FillValve := LowFloat AND NOT HighFloat;

END_PROGRAM
END
